/// The five `ItemVariant`s (`GameContent/Items/ItemVariants.cs:112-116`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ItemVariant {
    Stronger,
    Weaker,
    Rebalanced,
    Enabled,
    DisabledBossSummon,
}

/// The four world-seed conditions (`ItemVariants.cs:117-120`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SeedCondition {
    RemixWorld,
    GetGoodWorld,
    Mechdusa,
    Skyblock,
}

/// Fields a `Variant` stat-delta branch touches (the union over
/// `Item.cs`'s 26 `this.Variant ==/!=` branches).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VField {
    Rare,
    Value,
    Damage,
    UseTime,
    UseAnimation,
    Mana,
    Defense,
    UseStyle,
    Consumable,
    Material,
    AutoReuse,
    KnockBack,
    Shoot,
    ShootSpeed,
    Scale,
    UseTurn,
    Width,
    Height,
    BuffType,
    Ammo,
    MaxStack,
    Melee,
    Ranged,
    Magic,
    Summon,
    Thrown,
    Hammer,
    Pick,
    Axe,
    TileBoost,
    Bait,
    Crit,
    UseAmmo,
    NoMelee,
    NoUseGraphic,
    Channel,
    ReuseDelay,
    BuffTime,
    HealLife,
    Potion,
    Accessory,
    Vanity,
    HeadSlot,
    BodySlot,
    LegSlot,
    PlaceStyle,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VVal {
    Int(i64),
    Float(f32),
    Bool(bool),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VOp {
    Set(VField, VVal),
}

/// One row of the ItemVariants data:
/// - `condition: Some(c)` — a registration row (`ItemVariants.AddVariant`,
///   `ItemVariants.cs:121-145`); `variants::select` gates on it.
/// - `condition: None` — a delta row from an in-case `Variant ==` branch, or a
///   restore row for a `Variant !=` branch (the branch body applies to the
///   no-variant state; the restore row reverses it when the variant IS
///   selected); `variants::apply` consumes `set`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VariantOverride {
    pub id: u16,
    pub variant: ItemVariant,
    pub condition: Option<SeedCondition>,
    pub set: &'static [VOp],
}

